// Times sets number of times Conn.NewStream should be invoked
func (mmNewStream *mClientConnInterfaceMockNewStream) Times(n uint64) *mClientConnInterfaceMockNewStream {
	if n == 0 {
		mmNewStream.mock.t.Fatalf("Times of ClientConnInterfaceMock.NewStream mock can not be zero")
	}
	mm_atomic.StoreUint64(&mmNewStream.expectedInvocations, n)
	mmNewStream.expectedInvocationsOrigin = minimock.CallerInfo(1)
	return mmNewStream
}

func (mmNewStream *mClientConnInterfaceMockNewStream) invocationsDone() bool {
	if len(mmNewStream.expectations) == 0 && mmNewStream.defaultExpectation == nil && mmNewStream.mock.funcNewStream == nil {
		return true
	}

	totalInvocations := mm_atomic.LoadUint64(&mmNewStream.mock.afterNewStreamCounter)
	expectedInvocations := mm_atomic.LoadUint64(&mmNewStream.expectedInvocations)

	return totalInvocations > 0 && (expectedInvocations == 0 || expectedInvocations == totalInvocations)
}

// NewStream implements Conn
func (mmNewStream *ClientConnInterfaceMock) NewStream(ctx context.Context, sp1 *grpc.StreamDesc, s1 string, p1 ...grpc.CallOption) (c2 grpc.ClientStream, err error) {
	mm_atomic.AddUint64(&mmNewStream.beforeNewStreamCounter, 1)
	defer mm_atomic.AddUint64(&mmNewStream.afterNewStreamCounter, 1)

	mmNewStream.t.Helper()

	if mmNewStream.inspectFuncNewStream != nil {
		mmNewStream.inspectFuncNewStream(ctx, sp1, s1, p1...)
	}

	mm_params := ClientConnInterfaceMockNewStreamParams{ctx, sp1, s1, p1}

	// Record call args
	mmNewStream.NewStreamMock.mutex.Lock()
	mmNewStream.NewStreamMock.callArgs = append(mmNewStream.NewStreamMock.callArgs, &mm_params)
	mmNewStream.NewStreamMock.mutex.Unlock()

	for _, e := range mmNewStream.NewStreamMock.expectations {
		if minimock.Equal(*e.params, mm_params) {
			mm_atomic.AddUint64(&e.Counter, 1)
			return e.results.c2, e.results.err
		}
	}

	if mmNewStream.NewStreamMock.defaultExpectation != nil {
		mm_atomic.AddUint64(&mmNewStream.NewStreamMock.defaultExpectation.Counter, 1)
		mm_want := mmNewStream.NewStreamMock.defaultExpectation.params
		mm_want_ptrs := mmNewStream.NewStreamMock.defaultExpectation.paramPtrs

		mm_got := ClientConnInterfaceMockNewStreamParams{ctx, sp1, s1, p1}

		if mm_want_ptrs != nil {

			if mm_want_ptrs.ctx != nil && !minimock.Equal(*mm_want_ptrs.ctx, mm_got.ctx) {
				mmNewStream.t.Errorf("ClientConnInterfaceMock.NewStream got unexpected parameter ctx, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmNewStream.NewStreamMock.defaultExpectation.expectationOrigins.originCtx, *mm_want_ptrs.ctx, mm_got.ctx, minimock.Diff(*mm_want_ptrs.ctx, mm_got.ctx))
			}

			if mm_want_ptrs.sp1 != nil && !minimock.Equal(*mm_want_ptrs.sp1, mm_got.sp1) {
				mmNewStream.t.Errorf("ClientConnInterfaceMock.NewStream got unexpected parameter sp1, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmNewStream.NewStreamMock.defaultExpectation.expectationOrigins.originSp1, *mm_want_ptrs.sp1, mm_got.sp1, minimock.Diff(*mm_want_ptrs.sp1, mm_got.sp1))
			}

			if mm_want_ptrs.s1 != nil && !minimock.Equal(*mm_want_ptrs.s1, mm_got.s1) {
				mmNewStream.t.Errorf("ClientConnInterfaceMock.NewStream got unexpected parameter s1, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmNewStream.NewStreamMock.defaultExpectation.expectationOrigins.originS1, *mm_want_ptrs.s1, mm_got.s1, minimock.Diff(*mm_want_ptrs.s1, mm_got.s1))
			}

			if mm_want_ptrs.p1 != nil && !minimock.Equal(*mm_want_ptrs.p1, mm_got.p1) {
				mmNewStream.t.Errorf("ClientConnInterfaceMock.NewStream got unexpected parameter p1, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmNewStream.NewStreamMock.defaultExpectation.expectationOrigins.originP1, *mm_want_ptrs.p1, mm_got.p1, minimock.Diff(*mm_want_ptrs.p1, mm_got.p1))
			}

		} else if mm_want != nil && !minimock.Equal(*mm_want, mm_got) {
			mmNewStream.t.Errorf("ClientConnInterfaceMock.NewStream got unexpected parameters, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
				mmNewStream.NewStreamMock.defaultExpectation.expectationOrigins.origin, *mm_want, mm_got, minimock.Diff(*mm_want, mm_got))
		}

		mm_results := mmNewStream.NewStreamMock.defaultExpectation.results
		if mm_results == nil {
			mmNewStream.t.Fatal("No results are set for the ClientConnInterfaceMock.NewStream")
		}
		return (*mm_results).c2, (*mm_results).err
	}
	if mmNewStream.funcNewStream != nil {
		return mmNewStream.funcNewStream(ctx, sp1, s1, p1...)
	}
	mmNewStream.t.Fatalf("Unexpected call to ClientConnInterfaceMock.NewStream. %v %v %v %v", ctx, sp1, s1, p1)
	return
}

// NewStreamAfterCounter returns a count of finished ClientConnInterfaceMock.NewStream invocations
func (mmNewStream *ClientConnInterfaceMock) NewStreamAfterCounter() uint64 {
	return mm_atomic.LoadUint64(&mmNewStream.afterNewStreamCounter)
}

// NewStreamBeforeCounter returns a count of ClientConnInterfaceMock.NewStream invocations
func (mmNewStream *ClientConnInterfaceMock) NewStreamBeforeCounter() uint64 {
	return mm_atomic.LoadUint64(&mmNewStream.beforeNewStreamCounter)
}

// Calls returns a list of arguments used in each call to ClientConnInterfaceMock.NewStream.
// The list is in the same order as the calls were made (i.e. recent calls have a higher index)
func (mmNewStream *mClientConnInterfaceMockNewStream) Calls() []*ClientConnInterfaceMockNewStreamParams {
	mmNewStream.mutex.RLock()

	argCopy := make([]*ClientConnInterfaceMockNewStreamParams, len(mmNewStream.callArgs))
	copy(argCopy, mmNewStream.callArgs)

	mmNewStream.mutex.RUnlock()

	return argCopy
}

// MinimockNewStreamDone returns true if the count of the NewStream invocations corresponds
// the number of defined expectations
func (m *ClientConnInterfaceMock) MinimockNewStreamDone() bool {
	if m.NewStreamMock.optional {
		// Optional methods provide '0 or more' call count restriction.
		return true
	}

	for _, e := range m.NewStreamMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			return false
		}
	}

	return m.NewStreamMock.invocationsDone()
}

// MinimockNewStreamInspect logs each unmet expectation
func (m *ClientConnInterfaceMock) MinimockNewStreamInspect() {
	for _, e := range m.NewStreamMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to ClientConnInterfaceMock.NewStream at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterNewStreamCounter := mm_atomic.LoadUint64(&m.afterNewStreamCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.NewStreamMock.defaultExpectation != nil && afterNewStreamCounter < 1 {
		if m.NewStreamMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to ClientConnInterfaceMock.NewStream at\n%s", m.NewStreamMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to ClientConnInterfaceMock.NewStream at\n%s with params: %#v", m.NewStreamMock.defaultExpectation.expectationOrigins.origin, *m.NewStreamMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcNewStream != nil && afterNewStreamCounter < 1 {
		m.t.Errorf("Expected call to ClientConnInterfaceMock.NewStream at\n%s", m.funcNewStreamOrigin)
	}

	if !m.NewStreamMock.invocationsDone() && afterNewStreamCounter > 0 {
		m.t.Errorf("Expected %d calls to ClientConnInterfaceMock.NewStream at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.NewStreamMock.expectedInvocations), m.NewStreamMock.expectedInvocationsOrigin, afterNewStreamCounter)
	}
}

// MinimockFinish checks that all mocked methods have been called the expected number of times
func (m *ClientConnInterfaceMock) MinimockFinish() {
	m.finishOnce.Do(func() {
		if !m.minimockDone() {
			m.MinimockInvokeInspect()

			m.MinimockNewStreamInspect()
		}
	})
}

// MinimockWait waits for all mocked methods to be called the expected number of times
func (m *ClientConnInterfaceMock) MinimockWait(timeout mm_time.Duration) {
	timeoutCh := mm_time.After(timeout)
	for {
		if m.minimockDone() {
			return
		}
		select {
		case <-timeoutCh:
			m.MinimockFinish()
			return
		case <-mm_time.After(10 * mm_time.Millisecond):
		}
	}
}

func (m *ClientConnInterfaceMock) minimockDone() bool {
	done := true
	return done &&
		m.MinimockInvokeDone() &&
		m.MinimockNewStreamDone()
}
